/* =========================================================
   data-presets.js —— 内置热门二次元角色预设库
   ---------------------------------------------------------
   每张卡拆成两段，方便"随机补全"：
     core   = 角色识别核心（作品标签 + 人数性别 + 发型发色 + 瞳色 + 体型）
              只包含"这个人长什么样"，不含服装
     outfit = 原设服装（勾选"随机换装"时会被替换掉）
   base = core + ', ' + outfit，由 baseOfPreset() 在运行时拼出
   ========================================================= */

/* 把预设卡统一成"角色库"条目结构，与自建人物卡共用一套字段。
   区别只在 src：'preset' = 内置预设（core 与 outfit 分离，可随机换装），
                'mine'   = 自己建的（core 为空，base 独立存在）。 */
function presetToCard(c){
  return {
    id: 'p_' + c.id,
    src: 'preset',
    name: c.name,
    ip: c.ip,
    gender: c.gender,
    core: c.core,
    outfit: c.outfit,
    base: [c.core, c.outfit].filter(Boolean).join(', '),
    note: c.note || '',
    lora: c.lora || '',
    loraStrength: c.loraStrength != null ? c.loraStrength : null,
    preferredCkpt: c.preferredCkpt || '',
    preferredModel: c.preferredModel || '',
    ts: 0
  };
}

